def update_total_followers(apps, schema_editor):
    db_alias = schema_editor.connection.alias
    Project = apps.get_model("projects", "Project")

    for project in Project.objects.using(db_alias).all():
        total = project.followedprojects_set.count()
        # We can't use project.save(), because it will update dateUpdated
